  const items = Array.from(document.querySelectorAll("div.vehicle-card, div[data-tracking-id], phx-modal-trigger, div.vehicle-details"));
  // Or find all vehicle links and their parent card texts
  const links = Array.from(document.querySelectorAll("a[href*='/vehicledetail/']"));
  const results = [];
  const seen = new Set();
  for (const l of links) {
    const card = l.closest(".vehicle-card, .vehicle-card-main, [data-qa='vehicle-card']") || l.parentElement?.parentElement;
    const href = l.href;
    if (seen.has(href)) continue;
    seen.add(href);
    results.push({
      href,
      cardText: card ? card.innerText.replace(/\n+/g, " | ") : l.innerText
    });
  }
  return {
    totalLinks: links.length,
    distinct: results.length,
    sample: results.slice(0, 5)
  };
});
