const tabId = 480038377;

const listings = await browserjs(tabId, () => {
  // Find all cards
  // Let's inspect the cards DOM structure
  const cards = Array.from(document.querySelectorAll(".vehicle-card"));
  if (cards.length > 0) {
    return cards.map(c => ({
      title: c.querySelector(".title")?.innerText?.trim(),
      price: c.querySelector(".primary-price")?.innerText?.trim(),
      mileage: c.querySelector(".mileage")?.innerText?.trim(),
      dealer: c.querySelector(".dealer-name")?.innerText?.trim(),
      href: c.querySelector("a[href*='/vehicledetail/']")?.href
    }));
  }
  // If not .vehicle-card, let's look at all links containing vehicledetail
  const links = Array.from(document.querySelectorAll("a[href*='/vehicledetail/']"));
  return links.map(a => {
    let container = a;
    for (let i = 0; i < 5; i++) {
      if (!container.parentElement) break;
      container = container.parentElement;
      if (container.innerText.includes("$") && container.innerText.includes("mi.")) break;
    }
    return {
      href: a.href,
      text: container.innerText.replace(/\s+/g, ' ').slice(0, 200)
    };
  });
});

