const tabId = 480038377;
const details = await browserjs(tabId, () => {
  // Title / Heading
  const h1 = document.querySelector("h1")?.innerText?.trim();

  // Price
  const priceEl = document.querySelector(".primary-price, [data-qa='primary-price']") ||
                  Array.from(document.querySelectorAll("span, div")).find(el => el.innerText?.match(/^\$[0-9,]+$/));
  const price = priceEl?.innerText?.trim();

  // Mileage
  // Cars.com usually has a mileage block: "Mileage 43,648 mi" or dt/dd
  let mileage = null;
  const mileageEl = Array.from(document.querySelectorAll("div, dt, dd, span, p")).find(el => 
    el.innerText?.match(/^([0-9,]+)\s*(?:mi|miles)\.?$/i) || el.innerText?.match(/Mileage\s*\n*\s*([0-9,]+)\s*(?:mi|miles)/i)
  );
  if (mileageEl) {
    const m = mileageEl.innerText.match(/([0-9,]+)\s*(?:mi|miles)/i);
    if (m) mileage = m[1] + " mi";
  }
  if (!mileage) {
    // try body search specifically in vehicle breakdown or specs
    const m2 = document.body.innerText.match(/Mileage\s*\n*\s*([0-9,]+)\s*(?:mi|miles)/i);
    if (m2) mileage = m2[1] + " mi";
  }

  // Dealer location
  // Look for dealer info section
  let dealerName = null;
  let dealerAddress = null;
  const dealerHeaders = Array.from(document.querySelectorAll("h2, h3, div, p")).filter(el => el.innerText?.includes("Seller's info") || el.innerText?.includes("Dealership website"));

  // Also look for specific address regex (e.g. City, MN 55xxx or Street, City, MN)
  const addressMatch = document.body.innerText.match(/([0-9]+\s+[A-Za-z0-9\s.,]+,\s*[A-Za-z\s]+,\s*MN\s*[0-9]{5})/);
  if (addressMatch) {
    dealerAddress = addressMatch[1].replace(/\n+/g, ' ').trim();
  } else {
    const mnMatch = document.body.innerText.match(/([A-Za-z\s]+,\s*MN\s*[0-9]{5})/);
    if (mnMatch) dealerAddress = mnMatch[1].replace(/\n+/g, ' ').trim();
  }

  // Also check seller block
  const sellerInfo = Array.from(document.querySelectorAll("[data-qa='seller-name'], .seller-name, .dealer-name")).map(e => e.innerText?.trim()).filter(Boolean);

  return {
    h1,
    price,
    mileage,
    dealerAddress,
    sellerInfo,
    url: window.location.href
  };
});

