const urls = [
  "https://www.cars.com/vehicledetail/c4aa5e27-6b01-4dc0-8843-2e1ec66a23c1/",
  "https://www.cars.com/vehicledetail/75f5813f-0fa1-4c30-823d-128b451a0235/",
  "https://www.cars.com/vehicledetail/4555ffdf-6ed1-45f8-a236-f102202f0eb9/",
  "https://www.cars.com/vehicledetail/8212a4ed-0a4c-46bb-b00a-656271651318/"
];

const results = [];

for (const url of urls) {
  const tabRes = await tool.tabs_create({ url });
  const tabId = tabRes.details.tabId;
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 15000 });

  // check title / content
  const title = await browserjs(tabId, () => document.title);
  if (title.includes("Just a moment")) {
    console.log(`Tab ${tabId} hit Cloudflare`);
  }

  const data = await browserjs(tabId, () => {
    // Extract structured info from script or DOM
    let scriptData = null;
    try {
      const scripts = Array.from(document.querySelectorAll("script"));
      for (const s of scripts) {
        if (s.innerText.includes("call_source_dni_metadata")) {
          const m = s.innerText.match(/(\{"dealer_chat_provider".*\})/s);
          if (m) {
            scriptData = JSON.parse(m[1]);
            break;
          }
        }
      }
    } catch (e) {}

    const h1 = document.querySelector("h1")?.innerText?.trim();
    const price = document.querySelector(".primary-price, [data-qa='primary-price']")?.innerText?.trim();

    // Address
    const addressMatch = document.body.innerText.match(/([0-9]+\s+[A-Za-z0-9\s.,]+,\s*[A-Za-z\s]+,\s*MN\s*[0-9]{5})/);
    let address = addressMatch ? addressMatch[1].replace(/\n+/g, ' ').trim() : null;

    // Seller name
    const sellerHeader = document.body.innerText.match(/Seller's info\s*\n\s*([^\n]+)/);
    const sellerName = sellerHeader ? sellerHeader[1].trim() : null;

    return {
      h1,
      price,
      address,
      sellerName,
      scriptDims: scriptData?.call_source_dni_metadata?.dimensions,
      sellerZip: scriptData?.call_source_dni_metadata?.seller?.zipcode,
      city: scriptData?.call_source_dni_metadata?.user?.city,
      state: scriptData?.call_source_dni_metadata?.user?.state
    };
  });

  results.push({ tabId, url, data });
}

console.log(JSON.stringify(results, null, 2));

