for (const tabId of tabIds) {
  const row = await browserjs(tabId, () => {
    let scriptData = null;
    try {
      const scripts = Array.from(document.querySelectorAll("script"));
      for (const s of scripts) {
        if (s.innerText.includes("call_source_dni_metadata")) {
          const m = s.innerText.match(/(\{"dealer_chat_provider".*\})/s);
          if (m) {
            scriptData = JSON.parse(m[1]);
            break;
          }
        }
      }
    } catch (e) {}

    const h1 = document.querySelector("h1")?.innerText?.trim();
    const priceText = document.querySelector(".primary-price, [data-qa='primary-price']")?.innerText?.trim();

    // Mileage
    const mMatch = document.body.innerText.match(/Mileage\s*\n*\s*([0-9,]+)\s*(?:mi|miles)/i);
    let mileage = mMatch ? mMatch[1] : (scriptData?.call_source_dni_metadata?.dimensions?.mileage || "0");
    if (!mileage || mileage === "0") {
      const mNew = document.body.innerText.match(/([0-9,]+)\s*(?:mi\.|miles)/i);
      if (mNew && !mNew[0].includes("1,500")) mileage = mNew[1];
      else if (document.body.innerText.toLowerCase().includes("new 202")) mileage = scriptData?.call_source_dni_metadata?.dimensions?.mileage || "0";
    }

    // Dealer name and address
    let dealerAddress = null;
    const addressMatch = document.body.innerText.match(/([0-9]+\s+[A-Za-z0-9\s.,]+,\s*[A-Za-z\s]+,\s*MN\s*[0-9]{5})/);
    if (addressMatch) {
      dealerAddress = addressMatch[1].replace(/\n+/g, ' ').replace(/\s+/g, ' ').trim();
      const closesIdx = dealerAddress.indexOf("Closes");
      if (closesIdx !== -1) {
        const sub = dealerAddress.slice(closesIdx);
        const m = sub.match(/[0-9]+\s+[A-Za-z0-9\s.,]+,\s*[A-Za-z\s]+,\s*MN\s*[0-9]{5}/);
        if (m) dealerAddress = m[0];
      }
    }

    if (!dealerAddress && document.body.innerText.includes("1408 MN-13")) {
      dealerAddress = "1408 MN-13, Burnsville, MN 55337";
    }

    const sellerHeader = document.body.innerText.match(/Seller's info\s*\n\s*([^\n]+)/);
    const dealerName = sellerHeader ? sellerHeader[1].trim() : "";

    const dims = scriptData?.call_source_dni_metadata?.dimensions;
    const make = dims?.make?.[0] || "";
    const model = dims?.model?.[0] || "";
    const trim = dims?.trim?.[0] || "";
    const year = dims?.year || "";
    const price = priceText || ("$" + Number(dims?.price || 0).toLocaleString());

    let makeAndModel = `${make} ${model}`;
    if (trim) makeAndModel += ` ${trim}`;

    return {
      h1,
      makeAndModel,
      year,
      price,
      mileage: `${Number(String(mileage).replace(/,/g, '')).toLocaleString()} mi.`,
      dealerName,
      dealerAddress,
      city: scriptData?.call_source_dni_metadata?.user?.city,
      zip: scriptData?.call_source_dni_metadata?.seller?.zipcode,
      url: window.location.href.split('?')[0]
    };
  });

  vehicleData.push({ tabId, ...row });
}

