const rawData = await read("tmp://vehicle_data.json");
const vehicles = JSON.parse(rawData.text);

// Clean up mileage for new vehicles where needed (Atlas was 0 mi. new)
vehicles.forEach(v => {
  if (v.makeAndModel.includes("Atlas Peak Edition")) {
    v.mileage = "0 mi.";
  }
  if (v.dealerName && v.dealerAddress && !v.dealerAddress.includes(v.dealerName)) {
    v.fullDealerLocation = `${v.dealerName}, ${v.dealerAddress}`;
  } else {
    v.fullDealerLocation = v.dealerAddress || `${v.dealerName}, ${v.city}, MN ${v.zip}`;
  }
});

// Construct TSV:
// Header: Make and Model \t Model Year \t Price \t Mileage \t Dealership Location \t Link to Listing
const headers = ["Make and Model", "Model Year", "Price", "Mileage", "Dealership Location", "Link to Listing"];
const rows = [headers.join("\t")];

for (const v of vehicles) {
  rows.push([
    v.makeAndModel,
    v.year,
    v.price,
    v.mileage,
    v.fullDealerLocation,
    v.url
  ].join("\t"));
}

const tsv = rows.join("\n");
console.log("TSV preview:\n" + tsv);
await write("tmp://sheet_data.tsv", tsv);

